 form.onsubmit=e=>{e.preventDefault();try{state=collect();last=E.simulate(state,master,profile);localStorage.setItem(key,JSON.stringify(state));out.innerHTML=`<article class="panel"><h2>${esc(state.enemy.name)}への行動結果</h2><p class="notice">対象1体への計算対応した攻撃の合計 ${last.min.toLocaleString()} 〜 ${last.max.toLocaleString()}${last.estimated?' ／ 仮の職業能力を含む参考値':''}${last.complete?'':' ／ 未検証・未算定の効果あり'}</p><p>${esc(last.scope)}</p><p>有効領域：${esc(C.domains[last.domain.id].name)}（${last.domain.automatic?'配置から自動':'手動条件'}）</p>${last.domain.id==='newworld'&&last.worldColor?'<p>'+esc(C.newWorldEffects[last.worldColor])+'（被弾・回復・解除の戦闘処理は未対応）</p>':''}<details><summary>領域の上書き順・いきなり効果</summary><p>${last.domain.activations.map(x=>'キャラ'+(x.actor+1)+' '+esc(x.name)).join(' → ')||'領域なし'}</p>${last.initialLog.map(x=>'<p>キャラ'+(x.actor+1)+' '+esc(x.detail)+'</p>').join('')}</details><div class="character-grid">${last.builds.map((b,i)=>`<section><h3>キャラ${i+1} ${esc(master.jobs.find(j=>j.id===b.actor.job).name)}</h3><p>表示攻撃力 ${b.stats.attack}（${b.estimatedAttack?'仮の基礎能力＋装備から集計':'入力した実機値'}）<br>開幕速度 ${last.states[i].effectiveSpeed} ／ 攻魔 ${b.stats.magic} ／ コスト${b.cost}/${b.costLimit}</p><p>${b.heartParts.map(h=>esc(h.name)+' ×'+(h.factorLabel||h.factor)).join('<br>')}</p></section>`).join('')}</div><ol class="timeline">${last.logs.map(l=>`<li><strong>${l.turn||1}T ${l.order}番目 キャラ${l.actor+1} → ${esc(l.name)}</strong><p>${esc(l.detail)}</p>${root.BuffTimeline35?.action(l)||''}${l.damage?`<p>${l.damage.min.toLocaleString()} 〜 ${l.damage.max.toLocaleString()} ダメージ</p><details><summary>攻撃時のバフと計算値</summary><p>実際に残っている効果は上のバフ表示を参照してください。過去に付与されただけで失効した効果は含みません。</p><p>基礎値 ${l.damage.base} / 表示攻撃力へのバフ適用後 ${l.damage.effectiveAttack}</p><p>${Object.entries(l.damage.factors||{}).map(([k,v])=>esc(({mageChant:'魔響の詠唱',causality:'因果',skill:'技倍率',slash:'斬体・威力バフ',element:'属性ダメージ・FC',race:'系統特効',typeResistance:'斬体耐性・領域',elementResistance:'属性耐性・領域',elementDebuff:'FBなど属性弱化',criticalMin:'会心倍率下限',criticalMax:'会心倍率上限',criticalBoost:'会心強化',charge:'ため',dual:'二刀流補正'})[k]||k)+' ×'+Number(v.toFixed(3))).join(' / ')}</p><p>${l.damage.params.force?'通常フォース：装備とゾーンの属性補正を半減して適用。':'本来の属性、または強化フォース：属性補正を半減しない。'}${l.damage.element==='無'?' 無属性のため属性ダメージUP・属性弱化は適用しない。':''}</p><p>属性候補：${(l.damage.attributeCandidates||[]).map(d=>esc(d.element)+' '+d.min.toLocaleString()+'〜'+d.max.toLocaleString()).join(' / ')}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(l.damage.params,null,2))}</pre></details>`:''}<a href="${l.source}" target="_blank" rel="noreferrer">スキル出典</a></li>`).join('')}</ol>${last.notes.map(n=>`<p class="notice">${esc(n)}</p>`).join('')}<p>確率会心は不発として計算します。データの収集完了と全効果の計算対応は別です。未収録の職業固有効果と実機照合は残っています。継承錬度・開幕フォース・ゾーンは選択条件で計算します。</p></article>`;if(root.MeasurementUI36){const host=document.createElement('section');out.appendChild(host);root.MeasurementUI36.mount({target:host,result:last,configuration:state,profile,master});}status.textContent='選択した装備と行動順を保存しました。';}catch(error){out.innerHTML='';status.textContent=error.message;}};
 
 let worker=null,searchId=0;const ownerForm=form;const searchButton=target.querySelector('#gear-search'),cancelButton=target.querySelector('#gear-cancel'),gearStatus=target.querySelector('#gear-status'),gearOut=target.querySelector('#gear-output');
 const snapshotNow=()=>JSON.stringify({config:collect(),mode:target.querySelector('#gear-mode').value,action:target.querySelector('#gear-action').value,objective:target.querySelector('#gear-objective').value});
 const stop=()=>{searchId++;worker?.terminate();worker=null;searchButton.disabled=false;cancelButton.disabled=true;};
