 searchButton.onclick=()=>{try{const config=collect(),action=Number(target.querySelector('#gear-action').value),actor=config.actions[action].actor,objective=target.querySelector('#gear-objective').value,mode=target.querySelector('#gear-mode').value;E.simulate(config,master,profile);stop();const id=searchId,snapshot=snapshotNow();gearOut.innerHTML='';gearStatus.textContent='所持品の組合せを比較しています…';searchButton.disabled=true;cancelButton.disabled=false;worker=new Worker('workers/gear.js');worker.onerror=()=>{stop();gearStatus.textContent='探索を実行できませんでした。再読み込みして試してください。';};worker.onmessage=e=>{if(id!==searchId)return;if(!ownerForm.isConnected){stop();return;}if(e.data.progress){gearStatus.textContent='比較済み '+e.data.progress.nodes.toLocaleString()+' 組';return;}const data=e.data;stop();if(data.error){gearStatus.textContent=data.error;return;}if(snapshotNow()!==snapshot){gearStatus.textContent='条件が変わったため、もう一度探索してください。';return;}const r=data.result;gearStatus.textContent=r.nodes.toLocaleString()+'組を比較。'+(r.approximate?'候補を絞る近似探索です。全組合せの最適解は保証しません。'+(r.truncated?'探索上限で停止。':'段階探索を完了。'):r.truncated?'上限10万組で停止：ここまでの最良候補です。':'列挙可能な候補をすべて比較しました。');gearOut.innerHTML='<p>'+esc(r.scope)+'</p><p>元の攻撃：'+r.baseline.min.toLocaleString()+'〜'+r.baseline.max.toLocaleString()+'</p>'+r.results.map((b,n)=>'<article class="record-card"><h3>候補'+(n+1)+'：'+b.damage.min.toLocaleString()+'〜'+b.damage.max.toLocaleString()+' ダメージ</h3><p>比較基準で '+(b.damage[objective]-r.baseline[objective]).toLocaleString()+' 差／'+esc(b.damage.element)+'</p><p>攻撃力 '+b.stats.attack+'・すばやさ '+b.stats.speed+'</p>'+(b.actor?'<p>武器：'+esc(C.weapons.find(w=>w.id===b.actor.weapon)?.name)+' '+b.actor.limitBreak+'凸／得意補正：'+(b.actor.favored?'あり':'なし')+'</p><p>攻撃：'+esc(C.skills.find(k=>k.id===b.skill)?.name)+'</p><p>こころ：'+b.actor.hearts.map((id,j)=>'枠'+(j+1)+' '+esc(C.hearts.find(h=>h.id===id)?.name||'なし')).join(' / ')+'</p><p>こころコスト '+b.cost+'/'+b.costLimit+'／領域 '+esc(C.domains[b.domain.id].name)+'</p>':'')+(b.actor?.armors||b.armors).map((item,j)=>'<p>'+esc(['盾','頭','体上','体下','心珠1','心珠2','アクセ1','アクセ2'][j])+'：'+esc(master.items.find(x=>x.id===item)?.name||'なし')+'</p>').join('')+'<button type="button" data-apply-gear="'+n+'">この候補を装備欄へ反映</button></article>').join('')+r.limits.map(x=>'<p class="muted">'+esc(x)+'</p>').join('');gearOut.querySelectorAll('[data-apply-gear]').forEach(button=>button.onclick=()=>{if(snapshotNow()!==snapshot){gearStatus.textContent='条件が変わったため再探索してください。';return;}state=collect();const b=r.results[Number(button.dataset.applyGear)];if(b.actor){state.actors[actor]=b.actor;state.actions[action].skill=b.skill;}else{state.actors[actor].armors=b.armors;state.actors[actor].actualAttack=b.actualAttack;state.actors[actor].actualMagic=b.actualMagic;}localStorage.setItem(key,JSON.stringify(state));draw();target.querySelector('#sequence-status').textContent='候補を反映しました。「この装備・行動順で計算する」で倍率内訳を確認できます。';});};worker.postMessage({config,master,profile,options:{actor,action,objective,mode}});}catch(e){gearStatus.textContent=e.message;}};
